import{d as u,C as t,o as c,c as m,j as a,a as s,E as o,a3 as b}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"道德经第三十九章","description":"从万物得一到贵以贱为本，理解成就不离其母及不执玉石之形的读法。","frontmatter":{"title":"道德经第三十九章","description":"从万物得一到贵以贱为本，理解成就不离其母及不执玉石之形的读法。","category":"guide","aliases":["道德经第三十九章","老子第三十九章","dao de jing chapter 39"],"source":["王弼《道德真经注》卷三"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-39.md","filePath":"daoism/dao-de-jing/chapter-39.md","lastUpdated":1794189804000}'),g={name:"daoism/dao-de-jing/chapter-39.md"},_=u({...g,setup(p){const n=[{id:"the-one-and-their-accomplishments",label:"昔之得一者",showLabel:!0,sentences:[["昔之得",{text:"一",glossary:"yi"},"者：天得一以清，地得一以宁，神得一以灵，谷得一以盈，万物得一以生，",{text:"侯王",glossary:"houwang"},"得一以为天下",{text:"贞",glossary:"zhen"},"。"]],note:["【白话】自古那些得到一的：天由此清明，地由此安宁，神由此灵妙，川谷由此充盈，万物由此生长，侯王由此成为天下的正准。一在这里是这些成就所赖以成立的根本。","【王弼注择要】「一，数之始而物之极也。」注又说「物皆各得此一以成」，将清、宁、灵、盈、生、贞连到各物得一而成，不只把一当计数。","【读法】神属于本章古代天地万物的理解方式，本页不由此推出现代超自然效验。谷先取川谷；天下贞取天下的正准，不套用帛书另一语境的安定、纠正义。"]},{id:"losing-the-source-of-accomplishment",label:"其致之也",showLabel:!0,sentences:[["其致之也，谓天无以清将恐裂，地无以宁将恐",{text:"发",glossary:"fa"},"，神无以灵将恐",{text:"歇",glossary:"xie"},"，谷无以盈将恐",{text:"竭",glossary:"jie"},"，万物无以生将恐灭，侯王无以贵高将恐",{text:"蹶",glossary:"jue"},"。"]],note:["【白话】推说其后果：天失去赖以清明的根本，恐怕会破裂；地失去赖以安宁的根本，恐怕会动荡；神失去赖以灵妙的根本，恐怕会止息；川谷失去赖以充盈的根本，恐怕会枯竭；万物失去赖以生长的根本，恐怕会灭亡；侯王失去赖以尊贵高居的根本，恐怕会倾覆。","【王弼注择要】「用一以致清耳，非用清以清也。」又说「守一则清不失，用清则恐裂也」，并归结为「为功之母不可舍也」。本页据此以失去成就之本解释六个无以。","【读法】六句是与上段对应的警戒，不是现代天文、地质的机制说明。王弼特别辨成就所由与已经取得的成果，不能只靠反复维持清、贵等外观来代替守本。"]},{id:"the-lowly-as-the-root-of-the-honored",label:"贵以贱为本，高以下为基",showLabel:!0,sentences:[["故贵以",{text:"贱",glossary:"jian"},"为本，高以下为基。"],["是以侯王自称",{text:"孤",glossary:"gu"},"、",{text:"寡",glossary:"gua"},"、",{text:"不谷",glossary:"bugu"},"。"]],note:["【白话】所以尊贵以卑下为根本，高处以下方为基础。因此侯王用孤、寡、不谷这样的谦称称呼自己，表明尊贵不能自立，须记得它所依赖的卑下之本。","【王弼注择要】「贵在其母，而母无贵形。」王弼把贵贱、高下之喻接到成就的根本：根本不一定具有显贵的外形，却不能因此被舍弃。","【读法】贱在这里说处于卑下、不被尊显的一面，不表示人格低劣。不谷含不善、不贤的自谦义；称谓本身不能证明掌权者已经做到谦下，仍要看实际所为。"]},{id:"praise-traced-back-to-its-ground",label:"故致誉无誉",showLabel:!0,sentences:[["此非以贱为本",{text:"邪",glossary:"ye"},"？非乎？故",{text:"致誉",glossary:"zhiyu"},"无誉。"]],note:["【白话】这不正是以卑下为根本吗？难道不是吗？所以，将称誉推究到根本，反而没有一种固定的誉名可用来夸耀。这里的无誉，本页依王弼从根本不具显贵之形来理解。","【王弼注择要】「清不足贵，盈不足多。」注随贵在其母而母无贵形说「故致数誉乃无誉也」，将誉的判断由清、盈等成果转向其所由生的根本。","【读法】致誉一处有数誉、数舆等传本与解释分歧；本站保留致誉，所据录文作致数誉。本页暂循王注贵其母的线索，不把本句定成越追求名誉就一定越无名誉的因果格言。"]},{id:"jade-stone-and-fixed-form",label:"不欲琭琭如玉，珞珞如石",showLabel:!0,sentences:[["不欲",{text:"琭琭",glossary:"lulu"},"如玉，",{text:"珞珞",glossary:"luoluo"},"如石。"]],note:["【白话】不愿将自身固定为玉一般显美、石一般显实的样子。依本页所循王注，玉与石虽有贵贱之别，却都已被具体形态限定，不能据此代替成就万物的根本。","【王弼注择要】「玉石琭琭珞珞，体尽于形，故不欲也。」王弼把玉、石一并解释为受形所限，末句因而不是只在贵玉与贱石之间择其一。","【读法】琭琭通常释为玉有光泽貌；珞珞形容石的样子，具体形容义有分歧。本页依王注以玉石皆有形读全句，不据现有标点擅补宁愿作石的转折。"]}],r=[{id:"yi",term:"一",sense:1},{id:"houwang",term:"侯王",sense:1},{id:"zhen",term:"贞",sense:3},{id:"fa",term:"发",sense:1},{id:"xie",term:"歇",sense:1},{id:"jie",term:"竭",sense:1},{id:"jue",term:"蹶",sense:1},{id:"jian",term:"贱",sense:1},{id:"gu",term:"孤",sense:1},{id:"gua",term:"寡",sense:1},{id:"bugu",term:"不谷",sense:1},{id:"ye",term:"邪",sense:1,pinyin:"yé"},{id:"zhiyu",term:"致誉",sense:1},{id:"lulu",term:"琭琭",sense:1},{id:"luoluo",term:"珞珞",sense:1}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return c(),m("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第三十九章",tabindex:"-1"},[s("道德经第三十九章 "),a("a",{class:"header-anchor",href:"#道德经第三十九章","aria-label":'Permalink to "道德经第三十九章"'},"​")],-1)),o(i,{title:"已经清、宁、灵、盈，为什么仍不可失一",summary:"本章先列天地、神、谷、万物和侯王得一而成，再反写失去其本的危险，转入贵贱、高下的依存。王弼以不可舍为功之母贯通全章，末句玉石之喻仍指向不固守既成之形。",points:[{label:"先读",text:"得一不是机械地得到数字一，先看各物赖以成就的根本。"},{label:"再辨",text:"失本的后果与贵以贱为本相连，王侯自谦之称也要由此理解。"},{label:"后看",text:"致誉一句有传本与解释分歧，依王注从贵其母而不居成形读到玉石。"}],hint:"贞读 zhēn，本页取正准义；发读 fā，蹶读 jué；琭琭读 lù lù，珞珞读 luò luò。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),o(l,{sections:n,glossary:r}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),o(d,{lines:[{text:"天得一以清，地得一以宁，神得一以灵，谷得一以盈，万物得一以生，侯王得一以为天下贞。",tone:"成就须有所由",guide:"循王弼看各物成就赖以成立的一，不把清、宁等成果本身当作根本。"},{text:"故贵以贱为本，高以下为基。",tone:"高贵不能自立",guide:"把尊贵放回它所依存的基础，谦称也须落实到实际对待基础的方式。"},{text:"不欲琭琭如玉，珞珞如石。",tone:"不以既成之形自限",guide:"依王弼，玉石俱受形所限；末句仍应与不可舍其母、不可固居成果相连。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),o(h,{items:r}),e[4]||(e[4]=b('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-为什么先谈天地万物-再谈王侯的谦称" tabindex="-1">象：为什么先谈天地万物，再谈王侯的谦称？ <a class="header-anchor" href="#象-为什么先谈天地万物-再谈王侯的谦称" aria-label="Permalink to &quot;象：为什么先谈天地万物，再谈王侯的谦称？&quot;">​</a></h3><p>前段先说明各物由一而成、失本则有危险，后段把这条线索放到贵贱高下关系中。王侯的地位也不是凭空自立，孤、寡、不谷因而成为提醒其依存基础的例子。</p><h3 id="理-王弼为什么说非用清以清" tabindex="-1">理：王弼为什么说非用清以清？ <a class="header-anchor" href="#理-王弼为什么说非用清以清" aria-label="Permalink to &quot;理：王弼为什么说非用清以清？&quot;">​</a></h3><p>已经得到的清明是一种成果，使清明成立的根本却不能由清明的外观替代。若只守着成果而不问其所由，便是注中所说居成而失其母；贵以贱为本也是同一提醒。</p><h3 id="用-现代处境怎样借鉴得一而不居成" tabindex="-1">用：现代处境怎样借鉴得一而不居成？ <a class="header-anchor" href="#用-现代处境怎样借鉴得一而不居成" aria-label="Permalink to &quot;用：现代处境怎样借鉴得一而不居成？&quot;">​</a></h3><p>可以从具体成果反问支持它的条件：信任、基层工作、资源和长期维护是否仍在。这样的类比帮助检视依存关系，并不意味着一可以直接等同于现代某一个单一指标或管理口号。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>维护成果背后的基础。</strong> 当一个项目获得成绩时，继续关注维护者、使用者与日常工作是否得到支持。成绩的名号不能代替使成绩持续的条件。</p><p><strong>以实际行动检验谦逊。</strong> 少作一次自谦表态，多让基础工作有资源、让参与者能发声。若只借谦称增加好感，反会遮蔽原本需要看见的依赖。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我正引以为傲的成果，依靠哪些不显眼的人与条件？若只留下成绩的外观，哪些基础已经开始被我忽略？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>本站保留「其致之也，谓」，所据 HFL 录文经句作「其致之」后接注语，再续天无以清等句；本站「自称」「邪」与录文「自谓」「耶」分别列明。蹶与录文蹷、不谷与不穀作相应字形处理。</li><li>本站保留「故致誉无誉」，录文作「故致数誉无誉」；相关句另有数舆等传本读法，本页不据此默改。白话暂循王注贵其母而不居清盈之形理解，保留解释的限度。</li><li>六个无以依王弼不可舍为功之母解释；贞另列正准义，不混用既有易经守正义、帛书安定义。琭琭、珞珞的具体形容义与玉石的全句解释分开。</li><li>玉石末句依王弼体尽于形读为两者皆不可执定；这与取玉之贵或宁作石之贱的读法不同，页内注明所取，不将分歧抹平。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_003.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷三 HFL 本电子录文，004b–005b</a>。</p><p>字形字义参考：<a href="https://www.zdic.net/hans/%E7%90%AD" target="_blank" rel="noreferrer">汉典「琭」玉有光泽貌及旧注异说</a>。</p>',16))])}}});export{y as __pageData,_ as default};
